请对以下 case 进行三维加权评分。

=== case_id ===
Case-20-notif-aggregate-010

=== 用户原始指令 (query.txt) ===
帮我整个背景图上叠文字那种卡片，点开能跳app

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我整个背景图上叠文字那种卡片，点开能跳app",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "",
        "abilityName": "",
        "uri": "hwmusic://com.huawei.hmsapp.music/showMusicList?code=a001&type=4"
      }
    }
  ],
  "dataModelSchema": {
    "card": {
      "title": {
        "type": "string",
        "description": "背景图上叠加的主标题文本。",
        "sampleValue": "今日歌单"
      },
      "subtitle": {
        "type": "string",
        "description": "背景图上叠加的简短辅助说明。",
        "sampleValue": "30首推荐"
      },
      "actionHint": {
        "type": "string",
        "description": "整卡点击进入应用的短提示文本。",
        "sampleValue": "点开播放"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_music.png",
      "description": "音乐图标素材，适合用作音乐入口卡片的背景视觉锚点。"
    }
  ]
}

